css:
body :where([data-bz-node="cl"]) .bz-block{padding:0}
body :where([data-bz-node="cl"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="cl"]>.bz-container{padding-inline:0}

body [data-bz-node="cl"]{background:#fff;padding:90px 0}
body [data-bz-node="cl"]>.bz-container{max-width:var(--container)}
body [data-bz-node="cl-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;align-items:center}
body [data-bz-node="cl-copy"],body [data-bz-node="cl-media"]{grid-column:auto}
body [data-bz-node="cl-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:520px}
body [data-bz-node="cl-list"]{display:block;margin-top:26px}
body [data-bz-node^="cl-item-"]{display:block;margin-bottom:9px}
body [data-bz-node^="cl-item-"] p{position:relative;padding-left:20px;font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node^="cl-item-"] p::before{content:"";position:absolute;left:2px;top:9px;width:6px;height:6px;background:var(--accent)}
body [data-bz-node="cl-media"] figure{margin:0}
body [data-bz-node="cl-media"] img{width:100%;aspect-ratio:3/2;object-fit:cover;border-radius:0}
@media (max-width:1100px){body [data-bz-node="cl"]{padding:64px 24px}body [data-bz-node="cl-row"]{grid-template-columns:1fr;gap:32px}body [data-bz-node="cl-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="cl"]{padding:48px 20px}body [data-bz-node="cl-h"] h2{font-size:26px}}
